async function uploadSubmission(){
  if(!files.length||!submissionConfirmed||isSubmissionActionPending())return;
  if(draftCleanup?.key===draftKey){showSubmissionMessage("送信済みファイルの端末記録が残っています。新しい提出の前に「端末の後片付けを再試行」を押してください。");return;}
  if(files.some(file=>file.size<=0||file.size>MAX_SUBMISSION_FILE_SIZE)){showSubmissionMessage("空のファイルまたは50MBを超えるファイルは送信できません。選び直してください。");return;}
  const assignedJob=selectedJob?myJobs.find(job=>job.id===selectedJob.id):undefined;
  if(!assignedJob){showSubmissionMessage("提出する確定シフトを確認できません。シフト画面から案件を選び直してください。");return;}
  if(assignedJob.mailIntakeReviewRequired===true||(assignedJob.mailIntake&&(assignedJob.pendingSourceWrite===true||assignedJob.adminEditSheetWrite?.pending===true))||assignedJob.sourceMissing===true||assignedJob.applicationUnconfirmed===true||assignedJob.assignmentUnresolved===true){showSubmissionMessage("担当や原本の確認が完了していません。選択ファイルは保持しています。「シフトを更新」で状態を確認してください。");return;}
  if(Boolean(requestId&&(resubmissionDetail?.request.id!==requestId||resubmissionDetail.request.jobId!==selectedJob?.id||resubmissionDetail.request.type!==submissionType||resubmissionDetail.request.status!=="open"))){showSubmissionMessage("再提出できる依頼を確認できません。「提出情報を再読み込み」で最新の状態を確認してください。");return;}
  if(requestId&&resubmissionDetail?.request.scope!=="submission"&&files.length!==1){showSubmissionMessage("画像単位の再送は1ファイルだけ選択してください。選択内容を確認してください。");return;}
  const typeLabel=submissionType==="report"?"報告書":"売場画像";
  setSubmissionMessage("");
  if(!firebaseConfigured){
    setUploadState(Object.fromEntries(files.map(f=>[fileStateKey(f),"送信済み"])));
    showSubmissionMessage(`デモ：${typeLabel}を送信しました。`);
    setSubmissionConfirmed(false);
    return;
  }
  if(!functions||!firebaseApp){showSubmissionMessage("送信サービスの接続準備を確認できません。画面を再読み込みし、選択ファイルを確認してから再度送信してください。");return;}
  const activeFunctions=functions;

  const authLoadVersion=authLoadVersionRef.current;
  const isCurrentUpload=()=>authLoadVersion===authLoadVersionRef.current;
  const jobId=assignedJob.id;
  const currentRequestId=requestId;
  const currentType=submissionType;
  try{
    await run("uploadSubmission",async()=>{
      const {getClientStorage,ref,uploadBytesResumable}=await loadUploadStorage().catch(()=>{throw new Error("送信機能を読み込めませんでした。選択ファイルは保持しています。通信状態を確認して、もう一度送信してください。");});
      if(!isCurrentUpload())return;
      const activeStorage=getClientStorage();
      const purpose=currentRequestId?"replacement":"additional";
      const {prepareSubmissionAttempt,clearSubmissionAttempt}=await loadSubmissionAttempt().catch(()=>{throw new Error("再試行の準備機能を読み込めませんでした。選択ファイルは保持しています。通信状態を確認して、もう一度送信してください。");});
      const attempt=await prepareSubmissionAttempt(draftKey,files,files.map(submissionFileContentType),isCurrentUpload,assignedJob.mailIntake?assignedJob.revision:undefined);
      if(!isCurrentUpload())return;
      let r;
      try { r=await httpsCallable(activeFunctions,"createUploadSession")({clientRequestId:attempt.clientRequestId,...(attempt.expectedRevision!==undefined?{expectedRevision:attempt.expectedRevision}:{}),jobId,type:currentType,purpose,resubmissionRequestId:currentRequestId||undefined,files:files.map((f,index)=>({originalName:f.name,contentType:submissionFileContentType(f),size:f.size,contentSha256:attempt.contentHashes[index]}))}); }
      catch(error){
        const details=(error as {details?:{reason?:unknown;accepted?:unknown;clientRequestId?:unknown;expectedRevision?:unknown}})?.details;
        if(isCurrentUpload()&&details?.reason==="case_mail_submission_changed"&&details.accepted===false&&details.clientRequestId===attempt.clientRequestId&&details.expectedRevision===(attempt.expectedRevision??null))await clearSubmissionAttempt(attempt,isCurrentUpload);
        throw error;
      }
      if(!isCurrentUpload())return;
      const data=r.data as {submissionId:string;clientRequestId:string;files:{storagePath:string;uploadRequired:boolean}[]};
      if(!data||data.clientRequestId!==attempt.clientRequestId||typeof data.submissionId!=="string"||!data.submissionId.trim()||!Array.isArray(data.files)||data.files.length!==files.length||data.files.some(target=>!target||typeof target.uploadRequired!=="boolean"||typeof target.storagePath!=="string"||!target.storagePath.trim())||new Set(data.files.map(target=>target.storagePath)).size!==files.length)throw new Error("送信先を正しく準備できませんでした。もう一度お試しください。");
      const uploads=data.files.flatMap((target,index)=>{const file=files[index];return file?[{target,file}]:[];});
      setUploadState(Object.fromEntries(uploads.map(({file})=>[fileStateKey(file),"送信待ち"])));
      try{
      await runWithConcurrency(uploads,UPLOAD_CONCURRENCY,async({target,file})=>{
        if(!isCurrentUpload())throw new Error("ログイン状態が変わったため送信を中止しました。");
        const key=fileStateKey(file);
        if(!target.uploadRequired){if(isCurrentUpload())setUploadState(current=>({...current,[key]:"送信済み"}));return;}
        if(isCurrentUpload())setUploadState(current=>({...current,[key]:"送信中 0%"}));
        await new Promise<void>((resolve,reject)=>uploadBytesResumable(ref(activeStorage,target.storagePath),file,{contentType:submissionFileContentType(file),customMetadata:{lkcContentSha256:attempt.contentHashes[files.indexOf(file)]}}).on(
          "state_changed",
          snapshot=>{if(isCurrentUpload()){const progress=`送信中 ${Math.round(snapshot.bytesTransferred/Math.max(snapshot.totalBytes,1)*100)}%`;setUploadState(current=>current[key]===progress?current:{...current,[key]:progress});}},
          reject,
          resolve,
        ));
        if(isCurrentUpload())setUploadState(current=>({...current,[key]:"送信済み"}));
      });
      }catch(error){
        if(!isCurrentUpload())throw error;
        setUploadState(current=>Object.fromEntries(Object.entries(current).map(([key,status])=>[key,status==="送信済み"?status:status==="送信待ち"?"未送信":"送信未完了"])));
        throw new Error("送信を完了できませんでした。選択ファイルは保持しています。同じ選択ファイルで再度送信すると、受付済みのファイルを確認し、未送信分から続けます。「提出情報を再読み込み」でも履歴を確認できます。");
      }
      if(!isCurrentUpload())return;
      const durable=markDraftSubmitted(draftKey);
      const attemptCleared=durable&&await clearSubmissionAttempt(attempt,isCurrentUpload);
      if(!isCurrentUpload())return;
      skipNextDraftSaveRef.current=true;
      setFiles([]);
      setSubmissionConfirmed(false);
      const cleanupTarget={key:draftKey,durable,attempt,attemptCleared};
      setDraftCleanup(cleanupTarget);
      showSubmissionMessage(data.files.every(target=>!target.uploadRequired)
        ? `${typeLabel}は受付済みです。再アップロードせず、Drive転送の状況を確認しています…`
        : `${typeLabel}を送信しました。Drive転送を処理中です…`);
      void pollSubmissionProcessing(jobId,data.submissionId,currentType,currentRequestId);
      try{
        if(!attemptCleared)return;
        await clearDraft(draftKey);
        if(!isCurrentUpload())return;
        const receiptCleanup={...cleanupTarget,draftCleared:true};
        setDraftCleanup(current=>current===cleanupTarget?receiptCleanup:current);
        if(isCurrentUpload())setDraftCleanup(current=>current===receiptCleanup?null:current);
      }catch{
        // 送信済み。端末の後片付け失敗をアップロード失敗として扱わない。
      }
    },{setMessage:value=>{if(isCurrentUpload())showSubmissionMessage(value);}});
  }catch{return;}
}

async function retryDraftCleanup(){
  if(!draftCleanup||isPending("draft-cleanup")||isPending("uploadSubmission"))return;
  let target=draftCleanup;
  const authVersion=authLoadVersionRef.current;
  const isCurrent=()=>authVersion===authLoadVersionRef.current;
  const advance=(next:typeof target)=>{
    const previous=target;
    setDraftCleanup(current=>current===previous?next:current);
    target=next;
  };
  try{
    await run("draft-cleanup",async()=>{
      // The submitted marker alone cannot bind a saved draft to the files actually sent.
      if(!target.attempt&&!target.attemptCleared){advance({...target,unverified:true});return;}
      if(!target.durable){
        if(!markDraftSubmitted(target.key))return;
        advance({...target,durable:true});
      }
      if(!target.attemptCleared){
        const {clearSubmissionAttempt}=await loadSubmissionAttempt();
        if(!isCurrent()||!target.attempt)return;
        const cleared=await clearSubmissionAttempt(target.attempt,isCurrent);
        if(!isCurrent()||!cleared)return;
        advance({...target,attemptCleared:true,unverified:false});
      }
      if(!target.draftCleared){
        await clearDraft(target.key);
        if(!isCurrent())return;
      }
      setDraftCleanup(current=>current===target?null:current);
    });
  }catch{
    if(isCurrent())setDraftCleanup(current=>current===target?{...current,unverified:true}:current);
  }
}

hydration:
useEffect(()=>{
  setSubmissionConfirmed(false);
  hydratedDraftKeyRef.current="";
  draftHydratingRef.current=Boolean(draftKey);
  skipNextDraftSaveRef.current=false;
  setDraftHydrating(Boolean(draftKey));
  if(!draftKey)return;
  const submittedReceipt=getSubmittedDraftReceipt(draftKey);
  if(submittedReceipt)setDraftCleanup(current=>current?.key===draftKey?current:{key:draftKey,durable:submittedReceipt.durable});
  let active=true;
  void loadDraft(draftKey).then(draftFiles=>{
    if(!active)return;
    setFiles(draftFiles);
    hydratedDraftKeyRef.current=draftKey;
    skipNextDraftSaveRef.current=true;
    draftHydratingRef.current=false;
    setDraftHydrating(false);
  }).catch(()=>{
    if(!active)return;
    setFiles([]);
    hydratedDraftKeyRef.current=draftKey;
    skipNextDraftSaveRef.current=true;
    draftHydratingRef.current=false;
    setDraftHydrating(false);
    showSubmissionMessage("保存済みの下書きを読み込めませんでした。ファイルを選び直してください。");
  });
  return()=>{active=false;};
},[draftKey]);

draftSave:
const draftSavePaused=isPending("submission-context")||isPending("submission-files");
useEffect(()=>{
  if(!draftKey||draftHydrating||hydratedDraftKeyRef.current!==draftKey||draftSavePaused)return;
  if(skipNextDraftSaveRef.current){skipNextDraftSaveRef.current=false;return;}
  let active=true,timerPending=true;
  const pendingDraftKey=draftKey,pendingFiles=files,authVersion=authLoadVersionRef.current;
  const timer=setTimeout(()=>{
    timerPending=false;
    // 再描画前に解除が始まった場合も、古い選択内容を保存しない。
    if(isPending("submission-context")||isPending("submission-files"))return;
    void saveDraft(draftKey,files).catch(()=>{
      if(active&&hydratedDraftKeyRef.current===draftKey)showSubmissionMessage("下書きを保存できませんでした。選択中のファイルはこの画面から送信できます。画面を閉じる前に送信するか、端末の空き容量・保存設定を確認してください。");
    });
  },300);
  return()=>{
    active=false;clearTimeout(timer);
    if(timerPending&&!previewContextRef.current&&authVersion===authLoadVersionRef.current&&pendingFiles.length&&!isPending("submission-context")&&!isPending("submission-files")&&!getSubmittedDraftReceipt(pendingDraftKey)){
      void saveDraft(pendingDraftKey,pendingFiles).catch(()=>{if(authVersion===authLoadVersionRef.current&&!previewContextRef.current)setMessage("提出対象が見つからず、下書きも保存できませんでした。画面を閉じず、シフトを更新して対象を確認してください。");});
    }
  };
},[draftKey,draftHydrating,files,draftSavePaused]);

draftStore:
export type DraftFile = {
  id: string;
  name: string;
  type: string;
  size: number;
  lastModified: number;
  blob: Blob;
};

const DB_NAME = "lkc-submission-drafts";
const STORE = "drafts";
const draftMutations = new Map<string, Promise<void>>();
const submittedDrafts = new Map<string, number>();
const receiptKey = (key: string) => `lkc-submitted-draft:${key}`;

export function getSubmittedDraftReceipt(key: string): { durable: boolean } | null {
  try { if (localStorage.getItem(receiptKey(key)) === "1") return { durable: true }; } catch { /* メモリの記録を確認する。 */ }
  return submittedDrafts.has(key) ? { durable: false } : null;
}

function isSubmittedDraft(key: string): boolean {
  return getSubmittedDraftReceipt(key) !== null;
}

// IndexedDBの後片付けが失敗しても、送信済みの下書きを自動復元しない。
export function markDraftSubmitted(key: string): boolean {
  submittedDrafts.set(key, (submittedDrafts.get(key) ?? 0) + 1);
  try { localStorage.setItem(receiptKey(key), "1"); return true; } catch { return false; }
}

function enqueueDraftMutation(key: string, mutation: () => Promise<void>): Promise<void> {
  const previous = draftMutations.get(key) ?? Promise.resolve();
  const current = previous.catch(() => undefined).then(mutation);
  draftMutations.set(key, current);
  return current.finally(() => {
    if (draftMutations.get(key) === current) draftMutations.delete(key);
  });
}

async function waitForDraftMutation(key: string): Promise<void> {
  await draftMutations.get(key);
}

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE);
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export function saveDraft(key: string, files: File[]): Promise<void> {
  if (isSubmittedDraft(key)) return Promise.reject(new Error("送信済み下書きの後片付けを先に再試行してください。"));
  const records: DraftFile[] = files.map((file) => ({
    id: crypto.randomUUID(), name: file.name, type: file.type,
    size: file.size, lastModified: file.lastModified, blob: file,
  }));
  return enqueueDraftMutation(key, async () => {
    if (isSubmittedDraft(key)) throw new Error("送信済み下書きは保存し直しません。" );
    const db = await openDb();
    try {
      await tx(db, "readwrite", (store) => store.put(records, key));
    } finally {
      db.close();
    }
  });
}

export async function loadDraft(key: string): Promise<File[]> {
  if (isSubmittedDraft(key)) return [];
  await waitForDraftMutation(key);
  if (isSubmittedDraft(key)) return [];
  const records = await readDraftRecords(key);
  if (isSubmittedDraft(key)) return [];
  return draftFiles(records);
}

async function readDraftRecords(key: string): Promise<DraftFile[]> {
  const db = await openDb();
  let records: DraftFile[];
  try {
    records = await new Promise<DraftFile[]>((resolve, reject) => {
      const transaction = db.transaction(STORE, "readonly");
      const request = transaction.objectStore(STORE).get(key);
      // リクエスト成功後でもトランザクションが中断されることがある。
      transaction.oncomplete = () => resolve((request.result as DraftFile[] | undefined) ?? []);
      transaction.onerror = () => reject(transaction.error);
      transaction.onabort = () => reject(transaction.error ?? new DOMException("下書きの読み込みが中断されました。", "AbortError"));
      request.onerror = () => reject(request.error);
    });
  } finally {
    db.close();
  }
  return records;
}

function draftFiles(records: DraftFile[]): File[] {
  return records.map((record) => new File([record.blob], record.name, {
    type: record.type, lastModified: record.lastModified,
  }));
}

export function clearDraft(key: string): Promise<void> {
  const receiptVersion = submittedDrafts.get(key);
  return enqueueDraftMutation(key, async () => {
    const retained = isSubmittedDraft(key) ? await readDraftRecords(key) : [];
    const db = await openDb();
    try {
      await tx(db, "readwrite", (store) => store.delete(key));
      if (submittedDrafts.get(key) === receiptVersion && isSubmittedDraft(key)) {
        // 消去できた後にだけ送信済み印を外す。失敗時は再試行できる状態を保つ。
        try {
          localStorage.removeItem(receiptKey(key));
          if (localStorage.getItem(receiptKey(key)) !== null) throw new Error("送信済み印の削除を確認できません。");
        }
        catch (error) {
          // Preserve the saved draft if removing its durable marker fails.
          if (retained.length && localStorage.getItem(receiptKey(key)) === "1") {
            await tx(db, "readwrite", (store) => store.put(retained, key));
          }
          throw error;
        }
        submittedDrafts.delete(key);
      }
    } finally {
      db.close();
    }
  });
}

function tx(db: IDBDatabase, mode: IDBTransactionMode, action: (store: IDBObjectStore) => IDBRequest): Promise<void> {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE, mode);
    action(transaction.objectStore(STORE));
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);
    transaction.onabort = () => reject(transaction.error ?? new DOMException("下書きの保存処理が中断されました。", "AbortError"));
  });
}

attemptStore:
export type SubmissionAttempt = { clientRequestId: string; storageKey: string; contentHashes: string[]; expectedRevision?: number };
const failure = () => new Error("提出の再試行記録を保存できません。端末の保存設定を確認してください。選択ファイルは保持しています。");
async function digest(value: BufferSource): Promise<string> {
  return Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", value)), byte => byte.toString(16).padStart(2, "0")).join("");
}
export async function prepareSubmissionAttempt(
  draftKey: string, files: File[], contentTypes: string[], isCurrent: () => boolean = () => true, expectedRevision?: number
): Promise<SubmissionAttempt> {
  if (!draftKey || !files.length || files.length > 20 || contentTypes.length !== files.length || !crypto.subtle || !navigator.locks) throw failure();
  if (expectedRevision !== undefined && (!Number.isSafeInteger(expectedRevision) || expectedRevision < 0)) throw failure();
  const contentHashes: string[] = [];
  for (const file of files) {
    if (!isCurrent()) throw new Error("ログイン状態が変わったため送信を中止しました。");
    if (file.size <= 0 || file.size > 50 * 1024 * 1024) throw failure();
    // 50MBを20個まとめてメモリへ展開しない。
    contentHashes.push(await digest(await file.arrayBuffer()));
  }
  const fingerprint = await digest(new TextEncoder().encode(JSON.stringify([draftKey, files.map((file, index) => [file.name, file.size, contentTypes[index], contentHashes[index]])])));
  const storageKey = "lkc.submissionAttempt.v1:" + fingerprint;
  return navigator.locks.request(storageKey, { mode: "exclusive" }, () => {
    if (!isCurrent()) throw new Error("ログイン状態が変わったため送信を中止しました。");
    try {
      const existing = localStorage.getItem(storageKey);
      const value = existing === null ? { version: 1, clientRequestId: crypto.randomUUID(), ...(expectedRevision !== undefined ? { expectedRevision } : {}) } : JSON.parse(existing);
      if (value?.version !== 1 || typeof value.clientRequestId !== "string" || !/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(value.clientRequestId)) throw failure();
      if (value.expectedRevision !== undefined && (!Number.isSafeInteger(value.expectedRevision) || value.expectedRevision < 0)) throw failure();
      const encoded = JSON.stringify(value);
      localStorage.setItem(storageKey, encoded);
      if (localStorage.getItem(storageKey) !== encoded) throw failure();
      return { clientRequestId: value.clientRequestId, storageKey, contentHashes, ...(value.expectedRevision !== undefined ? { expectedRevision: value.expectedRevision } : {}) };
    } catch { throw failure(); }
  });
}
// True means this exact receipt is confirmed absent; a newer valid receipt is preserved.
export async function clearSubmissionAttempt(attempt: SubmissionAttempt, isCurrent: () => boolean = () => true): Promise<boolean> {
  try {
    return await navigator.locks.request(attempt.storageKey, { mode: "exclusive" }, () => {
      if (!isCurrent()) return false;
      const raw = localStorage.getItem(attempt.storageKey);
      if (raw === null) return true;
      const saved = JSON.parse(raw);
      if (saved?.version !== 1 || typeof saved.clientRequestId !== "string" ||
        !/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(saved.clientRequestId) ||
        (saved.expectedRevision !== undefined && (!Number.isSafeInteger(saved.expectedRevision) || saved.expectedRevision < 0))) return false;
      if (saved.clientRequestId !== attempt.clientRequestId) return true;
      localStorage.removeItem(attempt.storageKey);
      return localStorage.getItem(attempt.storageKey) === null;
    });
  } catch { return false; }
}
